{% set ns = namespace(items=[], tw=0.0, te=0.0, live=0) %}
{% for name, pw, en in plugs %}
  {% set w = states(pw)|float(0) %}
  {% set e = states(en)|float(0) %}
  {% if states(pw) not in ['unknown','unavailable'] %}{% set ns.live = ns.live + 1 %}{% endif %}
  {% set ns.items = ns.items + [[name, w, e, states(pw)]] %}
  {% set ns.tw = ns.tw + w %}
  {% set ns.te = ns.te + e %}
{% endfor %}
